<div class="modal-body"><label class="form-label" for="typeName">Nombre</label><input class="form-control mb-3" id="typeName" name="name" required maxlength="100"><div class="invalid-feedback"></div><label class="form-label" for="typeDescription">Descripción</label><textarea class="form-control mb-3" id="typeDescription" name="description" rows="3" maxlength="1000"></textarea><input type="hidden" name="is_active" value="1"><div class="form-check"><input class="form-check-input" type="checkbox" id="typeActive" checked><label class="form-check-label" for="typeActive">Tipo activo</label></div></div>